const cart = jsonData.cart;

// ===== TIER 2: Data Integrity =====
pm.test("Returned cart id matches the requested cartId", function () {
   pm.expect(cart.id).to.equal(pm.environment.get("cartId"));
});
pm.test("Items array contains exactly 1 item", function () {
   pm.expect(cart.items).to.be.an("array");
   pm.expect(cart.items.length).to.equal(1);
});
pm.test("Computed total price is greater than 0", function () {
   pm.expect(cart.total).to.be.a("number");
   pm.expect(cart.total).to.be.above(0);
});
pm.test("Item unit price x quantity does not exceed the cart total", function () {
   pm.expect(cart.items[0].unit_price * cart.items[0].quantity).to.be.at.most(cart.total);
});

// ===== TIER 3: JSON Schema Validation =====
const cartSchema = {
   type: "object",
   required: ["cart"],
   properties: {
      cart: {
         type: "object",
         required: ["id", "region_id", "currency_code", "items", "total"],
         properties: {
            id: { type: "string", pattern: "^cart_" },
            region_id: { type: "string" },
            currency_code: { type: "string" },
            email: { type: ["string", "null"] },
            total: { type: "number" },
            items: {
               type: "array",
               minItems: 1,
               items: {
                  type: "object",
                  required: ["id", "variant_id", "quantity", "unit_price"],
                  properties: {
                     id: { type: "string" },
                     variant_id: { type: "string" },
                     quantity: { type: "integer", minimum: 1 },
                     unit_price: { type: "number" }
                  }
               }
            }
         }
      }
   }
};

