   const valid = tv4.validate(jsonData, cartSchema);
   pm.expect(valid, tv4.error ? tv4.error.message : "").to.be.true;
});

// Ajv (reports every violation)
pm.test("Schema is valid (Ajv)", function () {
   const Ajv = require("ajv");
   const ajv = new Ajv({ allErrors: true });
   const validate = ajv.compile(cartSchema);
   const valid = validate(jsonData);
   pm.expect(valid, JSON.stringify(validate.errors)).to.be.true;
});
